// AI: below section was generated by an AI
// One-time extractor: turns the WLED web UI arrays in the build copy's generated headers
// (wled00/html_*.h, js_*.h: PROGMEM byte arrays + *_length, as flashed onto the device) into
// virtualdev/ui/<NAME>.gz|.bin|.txt files plus ui/manifest.json, so core_api.js can serve the
// exact bytes the ESP32 would send.
//
// Usage: node tmp_core/extract.js [--src <wled00 dir>]
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const zlib = require('node:zlib');
const crypto = require('node:crypto');

const DEF_SRC = 'C:\\Users\\DIGVIJ~1\\AppData\\Local\\Temp\\claude\\c--Users-DigvijayPatilLM-Downloads-WLED-main-WLED-main\\' +
  '1c74d954-61d4-48b6-a5ac-753d266cf64d\\scratchpad\\buildenv\\WLED\\wled00';
const argv = process.argv.slice(2);
const si = argv.indexOf('--src');
const SRC = si >= 0 ? argv[si + 1] : DEF_SRC;
const OUT = path.join(__dirname, '..', 'ui');

// source file for arrays whose header has no "Autogenerated from" line (html_ui.h, html_pix*.h)
const KNOWN_SRC = { PAGE_index: 'index.htm', PAGE_pixart: 'pixart/pixart.htm', PAGE_pxmagic: 'pxmagic/pxmagic.htm',
  PAGE_pixelforge: 'pixelforge/pixelforge.htm' };

// content type as ESPAsyncWebServer's CONTENT_TYPE_* constants
function typeOf(src, name) {
  const ext = path.extname(src || '').toLowerCase();
  if (ext === '.htm' || ext === '.html') return 'text/html';
  if (ext === '.js') return 'application/javascript';
  if (ext === '.css') return 'text/css';
  if (ext === '.ico') return 'image/x-icon';
  if (ext === '.json') return 'application/json';
  return name.startsWith('JS_') ? 'application/javascript' : 'text/html';
}

const files = fs.readdirSync(SRC).filter(f => /^(html|js)_.*\.h$/.test(f)).sort();
if (!files.length) { console.error('no html_*.h / js_*.h in ' + SRC); process.exit(1); }
fs.mkdirSync(OUT, { recursive: true });

const manifest = { generated: new Date().toISOString(), source: SRC, webBuildTime: null, entries: {} };
let errors = 0;

for (const f of files) {
  const text = fs.readFileSync(path.join(SRC, f), 'utf8');
  const bt = /#define WEB_BUILD_TIME (\d+)/.exec(text);
  if (bt) manifest.webBuildTime = Number(bt[1]);

  // byte arrays: [// Autogenerated from X] const uint16_t N_length = L; const uint8_t N[] PROGMEM = { ... };
  const reArr = /(?:\/\/ Autogenerated from (\S+?),[^\n]*\n)?\s*const uint16_t (\w+)_length = (\d+);\s*const uint8_t (\w+)\[\] PROGMEM = \{([\s\S]*?)\};/g;
  let m;
  while ((m = reArr.exec(text))) {
    const [, from, name, lenStr, name2, body] = m;
    if (name !== name2) { console.error(`${f}: length/array name mismatch ${name} vs ${name2}`); errors++; continue; }
    if (manifest.entries[name]) continue; // first definition wins (ifdef alternatives)
    const bytes = Buffer.from(body.match(/0x[0-9a-fA-F]{2}/g).map(h => parseInt(h, 16)));
    const len = Number(lenStr);
    if (bytes.length !== len) { console.error(`${f}: ${name} has ${bytes.length} bytes, _length says ${len}`); errors++; }
    const gzip = bytes[0] === 0x1f && bytes[1] === 0x8b;
    let rawLen = null;
    if (gzip) {
      try { rawLen = zlib.gunzipSync(bytes).length; } catch (e) { console.error(`${f}: ${name} gunzip failed: ${e.message}`); errors++; }
    }
    const src = from ? from.replace(/^wled00\/data\/+/, '') : (KNOWN_SRC[name] || null);
    const file = name + (gzip ? '.gz' : '.bin');
    fs.writeFileSync(path.join(OUT, file), bytes);
    manifest.entries[name] = { file, header: f, src, length: len, gzip, rawLength: rawLen, type: typeOf(src, name),
      sha1: crypto.createHash('sha1').update(bytes).digest('hex') };
  }

  // plain PROGMEM strings (PAGE_msg, PAGE_dmxmap): const char N[] PROGMEM = R"=====(...)=====";
  const reStr = /(?:\/\/ Autogenerated from (\S+?),[^\n]*\n)?const char (\w+)\[\] PROGMEM = R"=====\(([\s\S]*?)\)=====";/g;
  while ((m = reStr.exec(text))) {
    const [, from, name, body] = m;
    if (manifest.entries[name]) continue;
    const file = name + '.txt';
    fs.writeFileSync(path.join(OUT, file), body, 'utf8');
    const src = from ? from.replace(/^wled00\/data\/+/, '') : null;
    manifest.entries[name] = { file, header: f, src, length: Buffer.byteLength(body), gzip: false, rawLength: Buffer.byteLength(body),
      type: typeOf(src, name), sha1: crypto.createHash('sha1').update(body).digest('hex') };
  }
}

fs.writeFileSync(path.join(OUT, 'manifest.json'), JSON.stringify(manifest, null, 1));
const names = Object.keys(manifest.entries);
console.log(`extracted ${names.length} arrays to ${OUT} (WEB_BUILD_TIME ${manifest.webBuildTime})`);
for (const n of names) {
  const e = manifest.entries[n];
  console.log(`  ${n.padEnd(24)} ${String(e.length).padStart(6)} B ${e.gzip ? 'gz ' : 'raw'} ${e.type.padEnd(22)} ${e.src || ''}`);
}
if (errors) { console.error(errors + ' error(s)'); process.exit(1); }
// AI: end
